{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Fluconazole, a related azole antifungal, has absolute oral bioavailability over 90% in humans, demonstrating that azole antifungals can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Halofantrine, a lipophilic poorly soluble drug, has an average absolute oral bioavailability of approximately 30% in fasted humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ziprasidone, a lipophilic drug with solubility-limited absorption, has oral bioavailability of 30% in the fasted state, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C72"],
      "claim": "Adinazolam has an absolute oral bioavailability of 39% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Mosliciguat has an absolute oral bioavailability of 23.1%, just above the 20% threshold, supporting that even low-to-moderate F values in this range are high.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is predicted high (F >= 20%) because the highest-transfer analogue fluconazole, an azole antifungal, shows near-complete oral bioavailability, and multiple other high-transfer analogues with lipophilic or poorly soluble character (halofantrine ~30%, ziprasidone 30%, adinazolam ~40%, mosliciguat 23%) all exceed the 20% threshold. No affirmative evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is provided; extrapolation relies on analogues.",
    "The query's low aqueous solubility may reduce F relative to fluconazole, but the available analogues above 20% mitigate this concern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

